<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import {ElMessage,ElMessageBox} from 'element-plus';
import {Search,Refresh,ArrowDown} from '@element-plus/icons-vue';
import {request,post,patch,put,remove} from '@/utils/request';
import {mallApi} from '@/api/mall/mall.api';
import {usePermissions} from '@/store/modules/permission.store';
const route=useRoute(),permissions=usePermissions(),isRole=computed(()=>route.path.endsWith('/roles'));
const members=ref<any[]>([]),roles=ref<any[]>([]),nodes=ref<string[]>([]),loading=ref(false),busy=ref(false);
const query=ref(''),searchType=ref('information'),roleFilter=ref(''),statusFilter=ref(''),page=ref(1),size=ref(20),selectedRows=ref<any[]>([]);
const labels:Record<string,string>={'shop.view':'查看店铺','shop.create':'创建／复制店铺','shop.edit':'编辑、绑定与常用','shop.open':'打开店铺','shop.delete':'店铺回收与删除','shop.export':'导出店铺','shop.grant':'管理店铺授权','device.view':'查看设备','device.edit':'编辑、检测与回收设备','device.buy':'购买设备','device.renew':'续费与加速','device.export':'导出设备','wallet.view':'查看余额','wallet.recharge':'账户充值','order.view':'查看订单','order.export':'导出订单','member.manage':'成员管理','role.manage':'角色管理'};
const memberTypes:Record<number,string>={1:'普通成员',2:'管理员',3:'超级管理员'};
async function load(){loading.value=true;try{[members.value,roles.value,nodes.value]=await Promise.all([request('/members'),request('/roles'),permissions.can('role.manage')?request('/permission-nodes'):Promise.resolve([])]);}finally{loading.value=false;}}
onMounted(()=>{load();if(route.query.create)editMember();});
watch([isRole,query,roleFilter,statusFilter],()=>page.value=1);
const roleMembers=(id:string)=>members.value.filter(m=>m.roles.includes(id));
const memberRoleNames=(m:any)=>m.owner?'企业所有者':roles.value.filter(r=>m.roles.includes(r.id)).map(r=>r.name).join('、')||'未分配';
const filtered=computed(()=>(isRole.value?roles.value:members.value).filter(row=>{
  if(statusFilter.value&&String(row.enabled)!==statusFilter.value)return false;
  if(!isRole.value&&searchType.value==='roles')return !roleFilter.value||row.roles.includes(roleFilter.value);
  const fields=isRole.value?[row.name,row.description,...roleMembers(row.id).map(m=>m.username)]:[row.username,row.displayName,row.phone];
  return fields.some(v=>String(v||'').toLowerCase().includes(query.value.toLowerCase()));
}));
const displayed=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value));
const memberDialog=ref(false),memberForm=reactive<any>({}),detail=ref<any>();
function editMember(row?:any){Object.keys(memberForm).forEach(k=>delete memberForm[k]);Object.assign(memberForm,row?{...row,password:''}:{username:'',displayName:'',phone:'',password:'',enabled:true});memberDialog.value=true;}
async function saveMember(){busy.value=true;try{if(memberForm.id)await patch('/members/'+memberForm.id,memberForm);else await post('/members',memberForm);memberDialog.value=false;await load();ElMessage.success('成员已保存');}finally{busy.value=false;}}
async function memberStatus(rows:any[],enabled:boolean){try{await ElMessageBox.confirm(`${enabled?'启用':'停用'}所选 ${rows.length} 名成员？`,'确认操作');}catch{return;}try{for(const row of rows)await patch('/members/'+row.id,{...row,enabled});}finally{await load();}}
const roleDialog=ref(false),roleForm=reactive<any>({}),copying=ref(false),category=ref('all');
function editRole(row?:any,copy=false){Object.keys(roleForm).forEach(k=>delete roleForm[k]);Object.assign(roleForm,row?{...row,permissions:[...row.permissions]}:{name:'',description:'',memberType:1,enabled:true,permissions:[]});if(copy){delete roleForm.id;roleForm.name+=' 副本';}copying.value=copy;category.value='all';roleDialog.value=true;}
async function saveRole(){busy.value=true;try{if(roleForm.id)await patch('/roles/'+roleForm.id,roleForm);else await post('/roles',roleForm);roleDialog.value=false;await load();}finally{busy.value=false;}}
async function roleStatus(row:any,enabled:boolean){await patch('/roles/'+row.id,{...row,enabled});await load();}
async function deleteRoles(rows:any[]){try{await ElMessageBox.confirm(`删除 ${rows.length} 个角色？相关成员将立即失去这些角色授予的权限。`,'删除角色',{type:'warning'});}catch{return;}try{for(const row of rows)await remove('/roles/'+row.id);}finally{await load();}}
const sections=computed(()=>['shop','device','wallet','order','member','role'].map(prefix=>({prefix,label:({shop:'店铺管理',device:'设备管理',wallet:'账户充值',order:'订单管理',member:'成员管理',role:'角色权限'} as Record<string,string>)[prefix],nodes:nodes.value.filter(n=>n.startsWith(prefix+'.'))})));
const visibleSections=computed(()=>sections.value.filter(s=>category.value==='all'||s.prefix===category.value));
function selectPermissions(list:string[],checked:boolean){roleForm.permissions=checked?[...new Set([...roleForm.permissions,...list])]:roleForm.permissions.filter((n:string)=>!list.includes(n));}
const assignDialog=ref(false),assignMode=ref<'member'|'role'>('member'),assigned=ref<string[]>([]),selected=ref<any>();
function assign(row:any,mode:'member'|'role'){selected.value=row;assignMode.value=mode;assigned.value=mode==='member'?[...row.roles]:roleMembers(row.id).map(m=>m.id);assignDialog.value=true;}
async function saveAssignments(){busy.value=true;try{if(assignMode.value==='member')await put(`/members/${selected.value.id}/roles`,{roles:assigned.value});else await put(`/roles/${selected.value.id}/members`,{members:assigned.value});assignDialog.value=false;await load();}finally{busy.value=false;}}
const grantsDialog=ref(false),grantMember=ref<any>(),shops=ref<any[]>([]),shopQuery=ref(''),selectedShops=ref<any[]>([]);
const displayedShops=computed(()=>shops.value.filter(s=>`${s.name} ${s.platform} ${s.accountName}`.toLowerCase().includes(shopQuery.value.toLowerCase())));
async function showGrants(member:any){grantMember.value=member;shopQuery.value='';shops.value=await request(`/members/${member.id}/environments`);grantsDialog.value=true;}
async function grantShops(rows:any[],revoke=false){busy.value=true;try{for(const shop of rows){if(revoke)await mallApi.revoke(shop.id,grantMember.value.id);else await mallApi.grant(shop.id,[grantMember.value.id]);}await showGrants(grantMember.value);ElMessage.success(revoke?'授权已撤销':'授权已保存');}finally{busy.value=false;}}
</script>
<template>
<section class="panel page-list"><h1 class="page-title">{{isRole?'角色管理':'成员管理'}}</h1>
  <div class="toolbar">
    <el-button v-if="isRole&&permissions.can('role.manage')" type="primary" @click="editRole()">新增角色</el-button>
    <template v-if="!isRole&&permissions.can('member.manage')"><el-button type="primary" @click="editMember()">添加成员</el-button><el-dropdown @command="memberStatus(selectedRows,$event==='enable')"><el-button :disabled="!selectedRows.length">更多操作<el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="enable">启用成员</el-dropdown-item><el-dropdown-item command="disable">停用成员</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template>
    <div class="company-search"><el-select v-if="!isRole" v-model="searchType" style="width:120px"><el-option label="成员信息" value="information"/><el-option label="角色" value="roles"/></el-select><el-select v-if="!isRole&&searchType==='roles'" v-model="roleFilter" clearable placeholder="选择角色" style="width:230px"><el-option v-for="r in roles" :key="r.id" :value="r.id" :label="r.name"/></el-select><el-input v-else v-model="query" :prefix-icon="Search" :placeholder="isRole?'搜索角色名称 / 成员账号 / 描述':'搜索成员账号 / 姓名 / 电话'" clearable style="width:280px"/><el-select v-model="statusFilter" clearable placeholder="状态筛选" style="width:110px"><el-option label="启用" value="true"/><el-option label="停用" value="false"/></el-select><el-button :icon="Refresh" aria-label="刷新列表" @click="load"/></div>
  </div>
  <el-table v-if="isRole" :data="displayed" v-loading="loading" row-key="id" @selection-change="selectedRows=$event">
    <el-table-column type="selection" width="45"/><el-table-column prop="name" label="角色名称" min-width="140" show-overflow-tooltip/><el-table-column label="成员类型" min-width="100"><template #default="{row}">{{memberTypes[row.memberType]}}</template></el-table-column>
    <el-table-column label="角色成员" min-width="160"><template #default="{row}"><el-tooltip :content="roleMembers(row.id).map(m=>m.username).join('、')||'暂无成员'"><span>{{roleMembers(row.id).slice(0,2).map(m=>m.username).join('、')||'—'}}<el-tag v-if="roleMembers(row.id).length>2" size="small">+{{roleMembers(row.id).length-2}}</el-tag></span></el-tooltip></template></el-table-column>
    <el-table-column prop="description" label="角色描述" min-width="180" show-overflow-tooltip/><el-table-column label="权限范围" width="100"><template #default="{row}"><el-tooltip :content="row.permissions.map((n:string)=>labels[n]).join('、')||'无功能权限'"><el-tag>{{row.permissions.length}} 项权限</el-tag></el-tooltip></template></el-table-column>
    <el-table-column label="状态" width="80"><template #default="{row}"><el-switch :model-value="row.enabled" :disabled="!permissions.can('role.manage')" @change="roleStatus(row,Boolean($event))"/></template></el-table-column>
    <el-table-column label="操作" width="250" fixed="right"><template #default="{row}"><template v-if="permissions.can('role.manage')"><el-button link type="primary" @click="editRole(row)">编辑</el-button><el-button link type="primary" @click="editRole(row,true)">复制角色</el-button><el-button link type="primary" @click="assign(row,'role')">绑定成员</el-button><el-button link type="danger" @click="deleteRoles([row])">删除</el-button></template></template></el-table-column>
  </el-table>
  <el-table v-else :data="displayed" v-loading="loading" row-key="id" @selection-change="selectedRows=$event"><el-table-column type="selection" width="45" :selectable="(row:any)=>!row.owner"/><el-table-column prop="username" label="成员账号" min-width="150"/><el-table-column prop="displayName" label="姓名" min-width="120"/><el-table-column label="角色" min-width="170"><template #default="{row}">{{memberRoleNames(row)}}</template></el-table-column><el-table-column prop="phone" label="联系电话" min-width="140"/><el-table-column label="状态" width="90"><template #default="{row}"><span :class="row.enabled?'status-enabled':'status-disabled'">● {{row.enabled?'启用':'停用'}}</span></template></el-table-column><el-table-column label="操作" width="265" fixed="right"><template #default="{row}"><template v-if="!row.owner"><el-button v-if="permissions.can('shop.grant')" link type="primary" @click="showGrants(row)">店铺授权</el-button><el-button v-if="permissions.can('member.manage')" link type="primary" @click="editMember(row)">编辑</el-button><el-button v-if="permissions.can('role.manage')" link type="primary" @click="assign(row,'member')">分配角色</el-button><el-dropdown trigger="click"><el-button link>更多<el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="detail=row">查看详情</el-dropdown-item><el-dropdown-item v-if="permissions.can('member.manage')" @click="editMember(row)">修改密码</el-dropdown-item><el-dropdown-item v-if="permissions.can('member.manage')" @click="memberStatus([row],!row.enabled)">{{row.enabled?'停用成员':'启用成员'}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template><el-button v-else link type="primary" @click="detail=row">查看详情</el-button></template></el-table-column></el-table>
  <div class="table-pagination"><div class="batch-actions"><span class="muted">已选 {{selectedRows.length}} 项</span><el-button v-if="isRole&&permissions.can('role.manage')" size="small" :disabled="!selectedRows.length" @click="deleteRoles(selectedRows)">批量删除</el-button></div><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[20,50,100]" :total="filtered.length" layout="total,sizes,prev,pager,next,jumper"/></div>
</section>
<el-dialog v-model="memberDialog" :title="memberForm.id?'编辑成员':'添加成员'" width="620px" :close-on-click-modal="false"><el-form label-width="100px"><el-form-item label="成员账号" required><el-input v-model="memberForm.username" :disabled="Boolean(memberForm.id)" maxlength="80"/></el-form-item><el-form-item label="姓名" required><el-input v-model="memberForm.displayName" maxlength="120"/></el-form-item><el-form-item label="联系电话"><el-input v-model="memberForm.phone" maxlength="40"/></el-form-item><el-form-item :label="memberForm.id?'重置密码':'登录密码'" :required="!memberForm.id"><el-input v-model="memberForm.password" type="password" show-password :placeholder="memberForm.id?'不修改请留空':'请输入至少 12 位密码'"/></el-form-item><el-form-item v-if="memberForm.id" label="成员状态"><el-radio-group v-model="memberForm.enabled"><el-radio :value="true">启用</el-radio><el-radio :value="false">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="memberDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveMember">保存</el-button></template></el-dialog>
<el-drawer v-model="roleDialog" :title="copying?'复制角色':roleForm.id?'编辑角色':'新增角色'" size="960px" :close-on-click-modal="false"><el-form label-position="top" class="field-grid"><el-form-item label="角色名称" required><el-input v-model="roleForm.name" maxlength="100" placeholder="请输入角色名称"/></el-form-item><el-form-item label="成员类型" required><el-select v-model="roleForm.memberType"><el-option v-for="(label,value) in memberTypes" :key="value" :value="Number(value)" :label="label"/></el-select></el-form-item><el-form-item label="角色描述" class="wide"><el-input v-model="roleForm.description" type="textarea" :rows="2" maxlength="200" show-word-limit/></el-form-item></el-form><h3 class="section-title">功能权限</h3><div class="permission-panel"><nav><button :class="{active:category==='all'}" @click="category='all'">全部分类 <span>{{roleForm.permissions?.length}}/{{nodes.length}}</span></button><button v-for="s in sections" :key="s.prefix" :class="{active:category===s.prefix}" @click="category=s.prefix">{{s.label}} <span>{{s.nodes.filter(n=>roleForm.permissions?.includes(n)).length}}/{{s.nodes.length}}</span></button></nav><div class="permission-content"><div class="permission-actions"><strong>{{category==='all'?'全部分类':sections.find(s=>s.prefix===category)?.label}}</strong><el-button link type="primary" @click="selectPermissions(visibleSections.flatMap(s=>s.nodes),true)">全选</el-button><el-button link type="primary" @click="selectPermissions(visibleSections.flatMap(s=>s.nodes),false)">清空已选</el-button></div><section v-for="s in visibleSections" :key="s.prefix" class="permission-section"><el-checkbox :model-value="s.nodes.every(n=>roleForm.permissions?.includes(n))" :indeterminate="s.nodes.some(n=>roleForm.permissions?.includes(n))&&!s.nodes.every(n=>roleForm.permissions?.includes(n))" @change="selectPermissions(s.nodes,Boolean($event))">{{s.label}}</el-checkbox><el-checkbox-group v-model="roleForm.permissions"><el-checkbox v-for="n in s.nodes" :key="n" :value="n">{{labels[n]}}</el-checkbox></el-checkbox-group></section></div></div><template #footer><el-button @click="roleDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveRole">保存</el-button></template></el-drawer>
<el-dialog v-model="assignDialog" :title="assignMode==='member'?'分配角色':'绑定成员'" width="600px"><p>{{selected?.name||selected?.displayName}}</p><el-select v-if="assignMode==='member'" v-model="assigned" multiple filterable placeholder="选择角色"><el-option v-for="r in roles" :key="r.id" :value="r.id" :label="r.name" :disabled="!r.enabled"/></el-select><el-select v-else v-model="assigned" multiple filterable placeholder="选择成员"><el-option v-for="m in members.filter(m=>!m.owner)" :key="m.id" :value="m.id" :label="`${m.displayName} (${m.username})`" :disabled="!m.enabled"/></el-select><template #footer><el-button @click="assignDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="saveAssignments">保存</el-button></template></el-dialog>
<el-drawer v-model="grantsDialog" :title="`店铺授权 · ${grantMember?.displayName||''}`" size="800px"><div class="toolbar"><el-button type="primary" :disabled="!selectedShops.length||!grantMember?.enabled" :loading="busy" @click="grantShops(selectedShops)">批量授权</el-button><el-button :disabled="!selectedShops.length" :loading="busy" @click="grantShops(selectedShops,true)">撤销授权</el-button><el-input v-model="shopQuery" placeholder="搜索店铺 / 平台 / 账号" clearable/></div><el-table :data="displayedShops" row-key="id" @selection-change="selectedShops=$event"><el-table-column type="selection" width="45"/><el-table-column prop="name" label="店铺名称"/><el-table-column prop="platform" label="平台"/><el-table-column prop="accountName" label="店铺账号"/><el-table-column label="授权状态" width="95"><template #default="{row}"><el-tag :type="row.granted?'success':'info'">{{row.granted?'已授权':'未授权'}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" :disabled="busy||(!row.granted&&!grantMember?.enabled)" @click="grantShops([row],row.granted)">{{row.granted?'撤销授权':'授权'}}</el-button></template></el-table-column></el-table></el-drawer>
<el-dialog :model-value="Boolean(detail)" title="成员详情" width="600px" @close="detail=undefined"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="成员账号">{{detail.username}}</el-descriptions-item><el-descriptions-item label="姓名">{{detail.displayName}}</el-descriptions-item><el-descriptions-item label="联系电话">{{detail.phone||'—'}}</el-descriptions-item><el-descriptions-item label="角色">{{memberRoleNames(detail)}}</el-descriptions-item><el-descriptions-item label="状态">{{detail.enabled?'启用':'停用'}}</el-descriptions-item></el-descriptions></el-dialog>
</template>
<style scoped>
.company-search{margin-left:auto;display:flex;gap:10px}.status-enabled{color:#52a76a}.status-disabled{color:#ef6262}.permission-panel{display:grid;grid-template-columns:180px 1fr;border:1px solid #e8edf5;min-height:360px}.permission-panel nav{background:#f7f9fc;padding:12px 0}.permission-panel nav button{width:100%;border:0;background:none;text-align:left;padding:14px 16px;color:#555;cursor:pointer}.permission-panel nav button.active{background:#eaf0ff;color:#386bff}.permission-panel nav span{float:right;font-size:12px}.permission-content{padding:16px}.permission-actions{display:flex;align-items:center;gap:15px;border-bottom:1px solid #edf0f5;padding-bottom:12px}.permission-actions strong{margin-right:auto}.permission-section{margin-top:16px}.permission-section>.el-checkbox{font-weight:600}.permission-section .el-checkbox-group{display:grid;grid-template-columns:1fr 1fr;padding-left:18px}
</style>
